referenceSolutions.javascript:
export function solve(arity, groups) {
  const args = [];
  for (const group of groups) {
    args.push(...group);
    if (args.length >= arity) return args.slice(0, arity).reduce((a, b) => a + b, 0);
  }
  return null;
}

